class Solution {
public:
    vector<int> maxValue(vector<int>& nums) {
        int n=nums.size();
        vector<int> suffix(n+1,INT_MAX),ans(n);
        for(int i=n-1;i>=0;--i) suffix[i]=min(nums[i],suffix[i+1]);
        int start=0,mx=INT_MIN;
        for(int i=0;i<n;++i) {
            mx=max(mx,nums[i]);
            if(mx<=suffix[i+1]) {
                for(int j=start;j<=i;++j) ans[j]=mx;
                start=i+1;mx=INT_MIN;
            }
        }
        return ans;
    }
};
